class Solution {
public:
    vector<int> findPattern(vector<vector<int>>& board, vector<string>& pattern) {
        int R = board.size(), C = board[0].size();
        int pR = pattern.size(), pC = pattern[0].size();
        for (int r = 0; r <= R - pR; ++r) {
            for (int c = 0; c <= C - pC; ++c) {
                vector<int> c2d(26, -1);
                vector<int> d2c(10, -1);
                bool match = true;
                for (int dr = 0; dr < pR && match; ++dr) {
                    for (int dc = 0; dc < pC && match; ++dc) {
                        char pch = pattern[dr][dc];
                        int val = board[r + dr][c + dc];
                        if (isdigit(pch)) {
                            if (pch - '0' != val) match = false;
                        } else {
                            int cid = pch - 'a';
                            if (c2d[cid] != -1 && c2d[cid] != val) match = false;
                            if (d2c[val] != -1 && d2c[val] != cid) match = false;
                            c2d[cid] = val;
                            d2c[val] = cid;
                        }
                    }
                }
                if (match) return {r, c};
            }
        }
        return {-1, -1};
    }
};

class Solution {
    public int[] findPattern(int[][] board, String[] pattern) {
        int R = board.length, C = board[0].length;
        int pR = pattern.length, pC = pattern[0].length();
        for (int r = 0; r <= R - pR; r++) {
            for (int c = 0; c <= C - pC; c++) {
                int[] c2d = new int[26];
                int[] d2c = new int[10];
                Arrays.fill(c2d, -1);
                Arrays.fill(d2c, -1);
                boolean match = true;
                for (int dr = 0; dr < pR && match; dr++) {
                    for (int dc = 0; dc < pC && match; dc++) {
                        char pch = pattern[dr].charAt(dc);
                        int val = board[r + dr][c + dc];
                        if (Character.isDigit(pch)) {
                            if (pch - '0' != val) match = false;
                        } else {
                            int cid = pch - 'a';
                            if (c2d[cid] != -1 && c2d[cid] != val) match = false;
                            if (d2c[val] != -1 && d2c[val] != cid) match = false;
                            c2d[cid] = val;
                            d2c[val] = cid;
                        }
                    }
                }
                if (match) return new int[]{r, c};
            }
        }
        return new int[]{-1, -1};
    }
}

var findPattern = function(board, pattern) {
    const R = board.length, C = board[0].length;
    const pR = pattern.length, pC = pattern[0].length;
    for (let r = 0; r <= R - pR; ++r) {
        for (let c = 0; c <= C - pC; ++c) {
            const c2d = {};
            const d2c = {};
            let match = true;
            for (let dr = 0; dr < pR && match; ++dr) {
                for (let dc = 0; dc < pC && match; ++dc) {
                    const pch = pattern[dr][dc];
                    const val = board[r + dr][c + dc];
                    if (pch >= '0' && pch <= '9') {
                        if (Number(pch) !== val) match = false;
                    } else {
                        if (c2d[pch] !== undefined && c2d[pch] !== val) match = false;
                        if (d2c[val] !== undefined && d2c[val] !== pch) match = false;
                        c2d[pch] = val;
                        d2c[val] = pch;
                    }
                }
            }
            if (match) return [r, c];
        }
    }
    return [-1, -1];
};
